"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[102],{9102:(e,t,i)=>{i.r(t),i.d(t,{PAPERS:()=>a});let a=[{id:"2610.11959",title:"MiMo-V2.6: Scaling Reinforcement Learning Towards Self-Improvement",up:63,href:"https://arxiv.org/abs/2610.11959",abstract:"Reinforcement learning (RL) is the central training paradigm for advancing large foundation models towards self-improvement. This report introduces the MiMo-V2.6 series, an omni-modal family that pushes the frontier of model intelligence by scaling RL compute. Prior to RL, we conduct mid-training on a broad multimodal corpus to provide ample exploration space, and build a solid infrastructure on the pretrained hybrid-SWA architecture to support subsequent scale-up. We scale RL compute along three dimensions: (1) larger batches and higher throughput, with an asynchronous training that consumes ",pdfUrl:"https://arxiv.org/pdf/2610.11959",primaryCategory:"cs.CL",published:"2026-10-08T00:00:00Z"},{id:"2610.12299",title:"Multi-Agent Egocentric World Model with Fine-Grained Embodied Interaction",up:46,href:"https://arxiv.org/abs/2610.12299",abstract:"Egocentric world models predict first-person observations conditioned on an agent's actions, but most focus on a single agent. Real embodied settings often involve multiple agents that act and interact within a shared environment. Existing multi-agent world models rely on coarse actions like locomotion, camera control, or discrete commands, leaving fine-grained embodied interactions underexplored. We formulate multi-agent egocentric world modeling as synchronized ego-stream generation for multiple agents interacting through fine-grained actions in a shared world. This requires cross-view actio",pdfUrl:"https://arxiv.org/pdf/2610.12299",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"2501.09223",title:"Foundations of Large Language Models",up:36,href:"https://arxiv.org/abs/2501.09223",abstract:"This is a book about large language models. As indicated by the title, it primarily focuses on foundational concepts rather than comprehensive coverage of all cutting-edge technologies. The book is structured into six main chapters, each exploring a key area: pre-training, generative models, prompting, alignment, inference, and reasoning. It is intended for college students, professionals, and practitioners in natural language processing and related fields, and can serve as a reference for anyone interested in large language models.",pdfUrl:"https://arxiv.org/pdf/2501.09223",primaryCategory:"cs.CL",published:"2026-10-08T00:00:00Z"},{id:"2610.12461",title:"OuroWorld: Bringing Any 3D World Alive as Diverse, Endlessly Looping 3D Cinemagraphs",up:34,href:"https://arxiv.org/abs/2610.12461",abstract:"Recent 3D world models generate photorealistic, explorable scenes that remain frozen in time. OuroWorld is a mask-free framework that turns any static 3D Gaussian Splatting scene into a 3D cinemagraph: a dynamic scene with vivid, diverse motion looping seamlessly from any viewpoint. A vision-language model infers plausible dynamics and guides a video model to synthesize a reference video, which we lift and complete into multi-view videos. To learn from this imperfect supervision, we propose Inconsistency-Robust Periodic 4DGS: a Fourier-series deformation field guarantees looping by constructio",pdfUrl:"https://arxiv.org/pdf/2610.12461",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"2610.09087",title:"U-Space: Uncovering When and Why Uncertainty Arises in Language Models",up:33,href:"https://arxiv.org/abs/2610.09087",abstract:"Large language models are informing decisions with ever-higher stakes. As the consequences of their errors grow, a central question becomes harder to ignore: how much can we trust an individual answer? Yet recognizing when to defer remains difficult because language models can present incorrect conclusions with fluent explanations and an authoritative tone. Uncertainty quantification seeks to address this disconnect by estimating the reliability of individual predictions. However, many existing methods require repeated generations or separately trained components, and their scalar estimates do",pdfUrl:"https://arxiv.org/pdf/2610.09087",primaryCategory:"cs.CL",published:"2026-10-06T00:00:00Z"},{id:"2610.12421",title:"Beyond Spatio-Temporal Priors: A Generalizable Approach for Dense Correspondence Matching",up:33,href:"https://arxiv.org/abs/2610.12421",abstract:"Dense correspondence matching has historically been bounded by simplifying spatio-temporal priors, such as smooth motion and rigid geometry. While effective for classical tasks, these assumptions break down in image editing and reference-guided generation (IEG), where transformations can preserve visual identity while breaking physical continuity. To establish identity-preserving correspondence across such transformations, we introduce FreeMatching, a generalizable framework combining generative and semantic foundation representations with heterogeneous supervision from classical datasets, tra",pdfUrl:"https://arxiv.org/pdf/2610.12421",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"2610.06801",title:"MC-Sparse: Deconstructing and Closing the Dense-Sparse Attention Gap in Diffusion Transformers",up:31,href:"https://arxiv.org/abs/2610.06801",abstract:"Sparse attention is a primary approach to reducing the latency of diffusion transformers in long-sequence generation tasks, such as video and high-resolution 3D asset generation. However, existing methods can degrade generation quality and fidelity at high sparsity levels. Through controlled oracle comparisons, we trace this degradation to three sources: constraints imposed by token grouping, inaccurate interaction selection, and the attention contributions lost when tokens are discarded. Guided by this analysis, we propose Meta-Cached Sparse Attention (MC-Sparse), a training-free framework th",pdfUrl:"https://arxiv.org/pdf/2610.06801",primaryCategory:"cs.CV",published:"2026-10-05T00:00:00Z"},{id:"2610.12289",title:"TestPrism: Rethinking Test Evaluation Beyond a Single Reference",up:29,href:"https://arxiv.org/abs/2610.12289",abstract:"Large language model (LLM) coding agents have advanced test generation across diverse programming tasks. However, the common practice of evaluating tests against a single reference solution overlooks alternative valid implementations and can overstate test quality. We introduce TestPrism, comprising 300 test tasks from 17 sources and 3000 candidate implementations, evenly split between valid and invalid solutions. Its primary metric, Joint Success Function, requires the generated tests to fail on the initial program state, accept every valid candidate, and reject every invalid candidate. Acros",pdfUrl:"https://arxiv.org/pdf/2610.12289",primaryCategory:"cs.SE",published:"2026-10-08T00:00:00Z"},{id:"2610.11794",title:"Memento 3: Model-Based Recursive Self-Improvement through Reflective Rulebooks",up:27,href:"https://arxiv.org/abs/2610.11794",abstract:"Learning to act in unfamiliar environments requires agents to infer how the world works and revise that understanding as new evidence arrives. Yet limited observations can support multiple world models that explain past interactions but predict different outcomes in unseen states. We introduce Memento 3, building on the Memento series to enable frozen LLM agents to continually learn explicit world models through external memory. The agent maintains a natural-language rulebook as persistent semantic memory, recording revisable hypotheses about environment dynamics while leaving unknown aspects ",pdfUrl:"https://arxiv.org/pdf/2610.11794",primaryCategory:"cs.AI",published:"2026-10-08T00:00:00Z"},{id:"2610.02967",title:"Post-Training Frontier Text-to-Image Models by Composing Preference and Rubric Rewards",up:25,href:"https://arxiv.org/abs/2610.02967",abstract:"Recent text-to-image generation models have achieved remarkable visual quality, but improving them through post-training remains challenging because no single reward signal captures the full range of human preference. In this work, we develop a simple and effective post-training recipe for open-domain text-to-image generation based on the composition of complementary reward signals. Our reward system consists of two main components: a preference reward, trained on large-scale human preference data using a Bradley-Terry objective to capture overall human aesthetic and perceptual preferences, an",pdfUrl:"https://arxiv.org/pdf/2610.02967",primaryCategory:"cs.CV",published:"2026-10-02T00:00:00Z"},{id:"2610.12419",title:"OneSearch-VL: Unified Multimodal Deep Research Agent for Image and Video",up:19,href:"https://arxiv.org/abs/2610.12419",abstract:"Single-image, multi-image, and video deep research require different visual operations but share a workflow of visual grounding, external retrieval, and fact composition. A key challenge is to preserve the dependencies linking localized visual anchors, entity relations, source-supported facts, and answer-producing operations. We introduce OneSearch-VL, a unified agent centered on the Visually Grounded Evidence Graph (VGEG), which encodes these dependencies as a shared task-level reference for data construction, process supervision, and operation-level evaluation. Our VGEG-based data engine con",pdfUrl:"https://arxiv.org/pdf/2610.12419",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"2610.12423",title:"Pumpire: Unified Benchmark for Metric Distance Estimation",up:15,href:"https://arxiv.org/abs/2610.12423",abstract:"We present Pumpire, a unified benchmark for evaluating metric point-pair distance estimation capability of both image- and video-level 3D foundation models, with or without depth priors. In contrast to previous approaches that normally evaluate depth and camera intrinsics separately or evaluate point-clouds with geometric similarity metrics, which cannot directly reflect models' point-to-point distance estimation capability, Pumpire directly assesses point-to-point distances from the reconstructed geometry. To this end, we collect a large-scale and diverse dataset (pumpire-6k) comprising 100 r",pdfUrl:"https://arxiv.org/pdf/2610.12423",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"2609.39068",title:"SparseEngine: Sparse-First Inference Engine",up:13,href:"https://arxiv.org/abs/2609.39068",abstract:"Long-context LLM agents accumulate interaction histories that strain KV-cache memory and attention computation. Although sparse attention reduces these costs, heterogeneous cache representations and workflows hinder integration with existing inference engines, while prior sparse-serving abstractions support only specific layouts or workflows. We present SparseEngine, a ground-up, sparse-first inference engine whose shared lifecycle contract lets each method control its KV representation and computation while coordinating state transitions with common serving infrastructure. SparseEngine suppor",pdfUrl:"https://arxiv.org/pdf/2609.39068",primaryCategory:"cs.LG",published:"2026-09-30T00:00:00Z"},{id:"2610.12369",title:"Embodied Turing Machines: Stateful Code for Robot Recursive Self-Improvement",up:12,href:"https://arxiv.org/abs/2610.12369",abstract:"Most robot policies keep a model in the control loop: a VLA maps observations to actions, and an Agent Harness, such as Agent-as-Policy or Harness VLA queries a VLM for decision making at run time. We propose a different view: the embodied world is an Embodied Turing Machine, whose tape is the robot and environment state and rules are the policy. If this state can be represented accurately, the decision making can be written entirely in code. We therefore propose Code-Only-as-Policy (COAP): code measures and tracks the robot, environment, and task state from camera images and proprioception, a",pdfUrl:"https://arxiv.org/pdf/2610.12369",primaryCategory:"cs.RO",published:"2026-10-08T00:00:00Z"},{id:"2610.12458",title:"OmniCapBench: A Deep-Structured Evaluation Framework for Fine-Grained Audio-Visual Captioning",up:12,href:"https://arxiv.org/abs/2610.12458",abstract:"Multimodal large language models (MLLMs) are rapidly evolving toward continuous audio--visual reasoning, creating an urgent need for evaluations that expose their capability limits. Audio--visual captioning is an ideal diagnostic task, yet current benchmarks face a coupled trade-off: whole-caption scores provide coverage without localization, local probes provide localization without coverage, and unconstrained LLM judges introduce instability. We introduce OmniCapBench (Omni-Video Caption Benchmark), a benchmark that reframes audio--visual caption evaluation as a deep-structured diagnostic fr",pdfUrl:"https://arxiv.org/pdf/2610.12458",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"2610.04977",title:"Do LLMs Understand Sequential Structure? A Controlled Study of Inference and Generation",up:11,href:"https://arxiv.org/abs/2610.04977",abstract:"Large language models (LLMs) are increasingly used as interactive agents and simulators, yet it remains unclear whether they can recover latent sequential structure beyond surface action frequencies. This distinction is critical for behavioral simulation, where actions are often shaped by prior context rather than marginal frequencies alone. We study this question using controlled two-player Rock--Paper--Scissors interactions and a one-player stochastic n-gram continuation task. Across these experiments, we test whether LLMs can identify latent strategies, follow simple Markov rules, and susta",pdfUrl:"https://arxiv.org/pdf/2610.04977",primaryCategory:"cs.AI",published:"2026-10-04T00:00:00Z"},{id:"2606.03335",title:"A GPU-Parallel Framework for Heterogeneous Multi-Task Reinforcement Learning",up:8,href:"https://arxiv.org/abs/2606.03335",abstract:"GPU-parallel simulation provides abundant robot interaction, but existing benchmarks rarely combine this scale with heterogeneous manipulation tasks and standardized multi-task RL evaluation. We introduce Hebero (Heterogeneous Benchmark for Robot Learning), a GPU-parallel Isaac Lab benchmark that enables efficient joint training and evaluation of a single policy across all 40 heterogeneous tasks. Scaling experiments show that increasing parallel replicas per task improves success under a fixed wall-clock budget. To support learning with sparse rewards and limited demonstrations, we propose Dem",pdfUrl:"https://arxiv.org/pdf/2606.03335",primaryCategory:"cs.RO",published:"2026-10-06T00:00:00Z"},{id:"2609.33987",title:"Opera: A Verbal Critic Framework for Long-horizon Coding Agents",up:8,href:"https://arxiv.org/abs/2609.33987",abstract:"Long-horizon coding agents need timely corrections, yet feedback can be ineffective or even harmful when it misjudges ongoing work or fails to address the underlying problem. Existing critics focus on evaluating trajectories and generating feedback, but rarely track what happens after feedback is delivered. We present Opera, a verbal critic framework that treats each correction as a persistent note, followed until the diagnosed problem is resolved. Opera decides when to review through periodic and event-driven triggers, diagnoses issues with typed operators, audits feedback against visible evi",pdfUrl:"https://arxiv.org/pdf/2609.33987",primaryCategory:"cs.CL",published:"2026-10-08T00:00:00Z"},{id:"2609.35433",title:"ReSPO: Reshaped Sequence Policy Optimization for Gradient Starvation in Off-Policy Learning",up:8,href:"https://arxiv.org/abs/2609.35433",abstract:"Reinforcement learning from verifiable rewards (RLVR) frequently reuses rollouts across multiple policy updates, increasing the mismatch between the current policy and the data-generating policy. We identify a sign-dependent gradient starvation problem in clipped policy optimization: clipping suppresses under-generated positive responses at the low-importance-weight tail while permitting severely over-generated negative responses to dominate the high-weight tail. To address this, we propose ReSPO (Reshaped Sequence Policy Optimization), which replaces clipping with a smooth, two-branch sequenc",pdfUrl:"https://arxiv.org/pdf/2609.35433",primaryCategory:"cs.LG",published:"2026-09-28T00:00:00Z"},{id:"2609.35855",title:"Mara Chain: Rethinking Failure as a Stepping Stone for AI System Auto-Evolution",up:5,href:"https://arxiv.org/abs/2609.35855",abstract:"Optimizing deployed AI systems increasingly amounts to editing prompts, skills, harnesses, and code rather than model weights. Existing approaches commonly optimize these artifacts through propose-evaluate-select procedures, where candidate configurations are evaluated and only those meeting an acceptance criterion are selected. Yet our analysis shows that discarded candidates often contain information critical for subsequent optimization. Discarding them causes later proposals to revisit the same failure modes. We introduce Mara Chain, a refinement procedure that turns rejected candidates int",pdfUrl:"https://arxiv.org/pdf/2609.35855",primaryCategory:"cs.LG",published:"2026-09-25T00:00:00Z"},{id:"2610.08927",title:"Can AI Agents Make Open-Ended Scientific Discovery? Evidence from Station",up:5,href:"https://arxiv.org/abs/2610.08927",abstract:"Recent AI systems have made rapid progress in scientific discovery when given well-defined metrics, but whether they can autonomously undertake open-ended scientific discovery remains unclear. We investigate AI's ability to tackle open-ended tasks in Station, an open-world environment in which multiple agents simulate a scientific ecosystem. To tackle challenges specific to open-ended tasks, we propose augmenting Station with two mechanisms: a Supervisor mechanism and periodic Meta Reflection, which encourage persistent exploration even when intermediate metrics are lacking. We construct open-",pdfUrl:"https://arxiv.org/pdf/2610.08927",primaryCategory:"cs.AI",published:"2026-10-06T00:00:00Z"},{id:"2610.11287",title:"REMORY: Learning Residual Memory for Context Compaction",up:5,href:"https://arxiv.org/abs/2610.11287",abstract:"Long-horizon agents compact their history to continue within a finite context window, but a textual summary alone may not support every subsequent decision. We introduce REMORY, a neural memory network that supplements the summary with a bounded sequence of soft memory tokens. Given the history and summary, the network learns to generate tokens that help a frozen LLM approximate the continuation it would produce with the full history. The tokens are conditioned on the summary and appended after it, forming an analogue of a residual connection along the sequence dimension. On SummHay, REMORY im",pdfUrl:"https://arxiv.org/pdf/2610.11287",primaryCategory:"cs.CL",published:"2026-10-08T00:00:00Z"},{id:"2610.12183",title:"A Closer Look at Agentic BBO: Benchmarking LLM Agents for Black-Box Optimization",up:4,href:"https://arxiv.org/abs/2610.12183",abstract:"Black-box optimization (BBO) arises in many scientific and engineering problems where objective evaluations are expensive and limited. Recent large language model (LLM) agents offer a new way to approach BBO by combining task semantics, computation, optimization tools, and feedback-driven decision making, showing great potential due to the integration with mathematically rigorous tools. However, existing agentic BBO studies use different task domains and system configurations, making their results difficult to compare and the effects of individual design choices hard to isolate. We therefore i",pdfUrl:"https://arxiv.org/pdf/2610.12183",primaryCategory:"cs.LG",published:"2026-10-08T00:00:00Z"},{id:"2610.12355",title:"Distilling Routed 3D Privilege for Spatial Reasoning in Vision-Language Models",up:4,href:"https://arxiv.org/abs/2610.12355",abstract:"Spatial reasoning remains a persistent weakness of vision-language models (VLMs), because RGB inputs do not directly provide geometric evidence. Existing remedies either inject 3D into the model at inference, paying architecture and latency costs, or train with outcome rewards that supervise only the final answer. Spatial errors originate in perception: a misjudged depth or direction can be corrected only by the scene's true geometry, which the 3D-scanned sources of spatial training corpora already provide. We propose GPD (Geometry-Privileged Distillation), which makes geometric evidence the p",pdfUrl:"https://arxiv.org/pdf/2610.12355",primaryCategory:"cs.CV",published:"2026-10-08T00:00:00Z"},{id:"W7171617880",title:"Machine-Speed Intrusion: A Detection Engineering Analysis of the July 2026 Hugging Face Agent Campaign",up:0,href:"https://doi.org/10.5281/zenodo.21686546",doi:"https://doi.org/10.5281/zenodo.21686546",year:2026,openalexId:"https://openalex.org/W7171617880"},{id:"W7171936549",title:"Could a Capability-Security Architecture Have Contained the July 2026 OpenAI-Hugging Face Agentic Exploit Chain?",up:0,href:"https://doi.org/10.5281/zenodo.21715175",doi:"https://doi.org/10.5281/zenodo.21715175",year:2026,openalexId:"https://openalex.org/W7171936549"},{id:"W7203931864",title:"hf-data-agent: a Hugging Face backed RAG data agent",up:0,href:"https://doi.org/10.5281/zenodo.22043399",doi:"https://doi.org/10.5281/zenodo.22043399",year:2026,openalexId:"https://openalex.org/W7203931864"}]}}]);